    domains: string[];
    hostPrefixes: Record<string, string>;
    excludePaths: TrackingConfig["excludePaths"];
    personalPaths: TrackingConfig["personalPaths"];
    personalMode: TrackingConfig["personalMode"];
    valueRedactions: TrackingConfig["valueRedactions"];
    variantParam: string | null;
    testParams: string[];
    notrackParam: string;
    storagePrefix: string;
    consent: TrackingConfig["consent"];
    legacyTrackAttributes: boolean;
    cta: TrackingConfig["cta"];
    messaging: TrackingConfig["messaging"];
    downloads: TrackingConfig["downloads"];
    notFound: TrackingConfig["notFound"];
    bookings: BookingAdapter[];
    bridges: TrackingConfig["bridges"];
    plugins: TrackingConfig["plugins"];
    firstTouch: TrackingConfig["firstTouch"];
    identify: TrackingConfig["identify"];
